def print_keys(d, indent=0):
    for k, v in d.items():
        print(' ' * indent + str(k))
        if isinstance(v, dict):
            print_keys(v, indent+2)
        elif isinstance(v, list):
            print(' ' * indent + f'List of {len(v)} items')
            if len(v) > 0 and isinstance(v[0], dict):
                print_keys(v[0], indent+2)

