import json

# Look more broadly for 2013 data in all bulletins
for year in [2011, 2012, 2013]:
    print(f'\\n=== Year {year} Bulletin ===')
    with open(f'/app/resources/treasury_bulletin_{year}_06.json', 'r') as f:
        data = json.load(f)

    for elem in data.get('document', {}).get('elements', []):
        content = elem.get('content', '') or ''
        if 'December 31' in content or 'Dec. 31' in content:
            if 'total assets' in content.lower():
                # Find which year this is for
                if 'Sept. 30, 2012' in content and 'Dec. 31, 2012' in content:
                    print('Year 2012 data (Dec 31, 2012):')
                    rows = content.split('</tr>')
                    for row in rows:
                        if 'Total assets' in row:
                            print(row)
